require_once __DIR__.'/config/db.php'; exigir_cliente();$q=$pdo->prepare('SELECT p.*,pr.nome_produto,pr.imagem FROM pedido p JOIN produtos pr ON pr.id_produto=p.id_produto WHERE p.id_cliente=? ORDER BY p.data_pedido DESC');$q->execute([$_SESSION['id_usuario']]);$pedidos=$q->fetchAll();$titulo='Meus pedidos — Florify';$descricao='Acompanhe seus pedidos';require __DIR__.'/partes/head.php';require __DIR__.'/partes/header.php';?>
<main class="secao container"><div class="text-center mb-5"><span class="eyebrow">Sua conta</span><h1 class="titulo-script grande">Meus pedidos</h1></div><?php if(!$pedidos):?><p class="text-center texto-corpo">Você ainda não realizou pedidos.</p><?php else:?><div class="row g-4"><?php foreach($pedidos as $o):?><div class="col-12"><article class="produtoCard p-4"><h3><?=florify_e($o['nome_produto'])?> · <?=$o['quantidade']?> unidade(s)</h3><p><strong>Total:</strong> R$ <?=number_format($o['valor_total'],2,',','.')?></p><p><strong>Entrega:</strong> <?=date('d/m/Y',strtotime($o['data_entrega']))?> — <?=florify_e($o['endereco_entrega'])?></p><p><strong>Pagamento:</strong> <?=florify_e($o['forma_pagamento'])?></p><p><strong>Status:</strong> <?=florify_e($o['status_pedido'])?></p></article></div><?php endforeach;?></div><?php endif;?></main><?php require __DIR__.'/partes/footer.php';require __DIR__.'/partes/scripts.php';?>
